// Obtain a defaults-initialized server config. Pure-by-value API; no persistent objects to return.
cn_server_config_t cfg = cn_server_config_defaults();
// Optionally touch a few fields to exercise structure access paths.
(void)cfg.connection_timeout;
(void)cfg.resend_rate;
// Validation: Function executed successfully; no heap allocation or persistent outputs are required.

// Construct both success and failure results and exercise cn_is_error.
cn_result_t ok = cn_error_success();
const char* msg = FUZZ_PARAM_STR().c_str();
cn_result_t fail = cn_error_failure(msg);
bool is_err_ok = cn_is_error(ok);
bool is_err_fail = cn_is_error(fail);
(void)is_err_ok; (void)is_err_fail;
// Validation: Ensures both code paths are exercised without requiring persistent objects.

// Construct a failure result with optional details.
const char* msg = FUZZ_PARAM_STR().c_str();
cn_result_t fail = cn_error_failure(msg);
(void)fail;
// Validation: Exercised constructor-by-value path; no persistent objects to return.

// Construct a success result.
